from collections import Counter,deque
def components(g,color=None):
    H=len(g);W=len(g[0]);dom=Counter(x for row in g for x in row).most_common(1)[0][0]
    mask=[[g[i][j]!=dom or (color is not None and g[i][j]==color) for j in range(W)] for i in range(H)]
    seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if mask[i][j] and (i,j) not in seen:
                q=deque([(i,j)]);seen.add((i,j));c=[]
                while q:
                    a,b=q.popleft();c.append((a,b))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and mask[x][y] and (x,y) not in seen:
                            seen.add((x,y));q.append((x,y))
                comps.append(c)
    return comps
